  "waitlist.confirm-page.bad": "That confirmation link is not valid. Nothing changed.",
  "waitlist.confirm-page.unavailable": "We could not confirm your address just now. Nothing changed, so please try the link again.",
  "waitlist.link-page.bad-title": "That link did not work",
  "waitlist.leave-page.title": "Leave the waitlist",
  "waitlist.leave-page.body": "Press the button to take this address off the {brand} waitlist. We record that you asked, and we will not write to it about the launch.",
  "waitlist.leave-page.submit": "Leave the waitlist",
