  "verification.fromRecord": "Lo que se verific\xF3",
  "verification.nav.blurb": "Quien comprueba nunca es quien hizo el trabajo.",
  "integrations.title": "Integraciones",
  "integrations.nav.blurb": "Lo que Orvay alcanza, y lo que a\xFAn no.",
  "departments.title": "Departamentos",
